exercises.solution:
function totalPanier(texte) {
  let panier;
  try {
    panier = JSON.parse(texte);
  } catch (erreur) {
    throw new Error("panier invalide");
  }
  if (!Array.isArray(panier)) {
    throw new Error("panier invalide");
  }
  return panier.reduce((total, a) => total + a.prix * a.quantite, 0);
}
